def is_task_schedulable(task_i):
    # This is a conceptual check, actual schedulability involves WCRT analysis
    for job in task_i.jobs:
        if job.completion_time > task_i.deadline_i:
            return False
    return True

def is_task_set_schedulable(task_set_gamma):
    for task_i in task_set_gamma:
        if not is_task_schedulable(task_i):
            return False
    return True

def suffers_interference(request_y, request_x):
    # Conceptual check based on timing intervals
    if request_y.is_pending() and request_x.is_being_served():
        return True
    return False

def suffers_intra_bank_interference(request_y, request_x):
    if request_x.target_bank == request_y.target_bank:
        if suffers_interference(request_y, request_x):
            return True
    return False

def suffers_inter_bank_interference(request_y, request_x):
    if request_x.target_bank != request_y.target_bank:
        if suffers_interference(request_y, request_x):
            return True
    return False

