def check_property_3(request_x, request_y):
    if request_x.target_bank == request_y.target_bank:
        # Can only be intra-bank interference
        return True
    else:
        # Can only be inter-bank interference
        return True
    # Cannot be both

def check_property_5(request_x, bank_u, reordering_threshold):
    # Conceptual check based on memory controller rules
    count_newer_promoted_interfering = 0
    for r_newer in get_requests_arrived_after(request_x, bank_u):
        if r_newer.is_row_hit() and r_newer.is_served_before(request_x):
            count_newer_promoted_interfering += 1
    return count_newer_promoted_interfering <= reordering_threshold

def check_property_6(request_x, bank_u, inter_bank_scheduler):
    if not inter_bank_scheduler.is_top_of_bank_queue(request_x, bank_u):
        return False # Not suffering direct inter-bank interference

    interfering_counts_per_other_bank = {}
    for bank_y in all_banks_except(bank_u):
        interfering_counts_per_other_bank[bank_y] = 0
        # Conceptual: simulate one round of round-robin
        if inter_bank_scheduler.serves_one_request_from_bank(bank_y):
            interfering_counts_per_other_bank[bank_y] += 1

    for bank_y in all_banks_except(bank_u):
        if interfering_counts_per_other_bank[bank_y] > 1:
            return False # Contradicts property
    return True

def bound_interfering_read_requests(node_i_j, processor_k, bank_u, time_t, task_set_gamma):
    read_requests_processor_k_bank_u_node_i_j_time_t = 0.0
    for task_h in task_set_gamma:
        for node_h_x in task_h.node_set_h:
            if node_h_x.processor_node_h_x == processor_k and node_h_x not in node_i_j.F_node_i_j:
                eta_h_x_time_t = 0.0
                if task_h == node_i_j.task_i:
                    eta_h_x_time_t = 1.0
                else:
                    eta_h_x_time_t = math.ceil((time_t + node_h_x.response_time_h_x) / node_h_x.period_h)
                read_requests_processor_k_bank_u_node_i_j_time_t += eta_h_x_time_t * node_h_x.read_requests_bank_u_node_h_x
    return read_requests_processor_k_bank_u_node_i_j_time_t

def bound_interfering_write_requests(node_i_j, processor_k, bank_u, time_t, task_set_gamma):
    write_requests_processor_k_bank_u_node_i_j_time_t = 0.0
    for task_h in task_set_gamma:
        for node_h_x in task_h.node_set_h:
            if node_h_x.processor_node_h_x == processor_k and node_h_x not in node_i_j.F_node_i_j:
                eta_h_x_time_t = 0.0
                if task_h == node_i_j.task_i:
                    eta_h_x_time_t = 1.0
                else:
                    eta_h_x_time_t = math.ceil((time_t + node_h_x.response_time_h_x) / node_h_x.period_h)
                write_requests_processor_k_bank_u_node_i_j_time_t += eta_h_x_time_t * node_h_x.write_requests_bank_u_node_h_x
    return write_requests_processor_k_bank_u_node_i_j_time_t

def bound_write_interference(node_i_j, time_t, bank_set_B, remote_processors_node_i_j, write_batch_size, write_buffer_size, latency_write_batch_func):
    # Calculate total_read_requests_time_t
    total_read_requests_time_t = 0.0
    for bank_u in bank_set_B:
        total_read_requests_time_t += node_i_j.read_requests_bank_u_node_i_j
        for processor_k in remote_processors_node_i_j:
            total_read_requests_time_t += bound_interfering_read_requests(node_i_j, processor_k, bank_u, time_t, task_set_gamma) # Assuming task_set_gamma is available

    # Calculate total_write_requests_time_t
    total_write_requests_time_t = 0.0
    for bank_u in bank_set_B:
        for processor_k in remote_processors_node_i_j:
            total_write_requests_time_t += bound_interfering_write_requests(node_i_j, processor_k, bank_u, time_t, task_set_gamma) # Assuming task_set_gamma is available

    bound1 = total_read_requests_time_t * write_batch_size
    bound2 = total_write_requests_time_t + write_buffer_size

    memory_contention_write_node_i_j_time_t = latency_write_batch_func(min(bound1, bound2))
    return memory_contention_write_node_i_j_time_t

def check_constraint_3(bank_u, remote_processors_node_i_j, intra_bank_promoted_k_u_map, read_requests_bank_u_node_i_j, reordering_threshold):
    sum_intra_bank_promoted = 0.0
    for processor_k in remote_processors_node_i_j:
        sum_intra_bank_promoted += intra_bank_promoted_k_u_map[processor_k][bank_u]
    return sum_intra_bank_promoted <= read_requests_bank_u_node_i_j * reordering_threshold

def check_constraint_4(bank_y, remote_processors_node_i_j, bank_set_B, inter_bank_interference_k_y_map, read_requests_bank_u_node_i_j_map, intra_bank_interference_k_u_map):
    lhs = 0.0
    for processor_k in remote_processors_node_i_j:
        lhs += inter_bank_interference_k_y_map[processor_k][bank_y]

    rhs_term1 = 0.0
    for bank_u in bank_set_B:
        if bank_u != bank_y:
            rhs_term1 += read_requests_bank_u_node_i_j_map[bank_u]

    rhs_term2 = 0.0
    for processor_k in remote_processors_node_i_j:
        for bank_u in bank_set_B:
            rhs_term2 += intra_bank_interference_k_u_map[processor_k][bank_u]

    return lhs <= (rhs_term1 + rhs_term2)

def check_constraint_5(bank_y, processor_k, remote_processors_node_i_j, bank_set_B, inter_bank_interference_k_y, read_requests_bank_u_node_i_j_map, intra_bank_interference_l_u_map):
    lhs = inter_bank_interference_k_y

    rhs_term1 = 0.0
    for bank_u in bank_set_B:
        if bank_u != bank_y:
            rhs_term1 += read_requests_bank_u_node_i_j_map[bank_u]

    rhs_term2 = 0.0
    for processor_l in remote_processors_node_i_j:
        if processor_l != processor_k:
            for bank_u in bank_set_B:
                # The proof implies bank_u != bank_y for inter-bank interference
                # but the formula as written sums over all bank_u for IR_intra_l_u
                # Following the formula as written:
                rhs_term2 += intra_bank_interference_l_u_map[processor_l][bank_u]

    return lhs <= (rhs_term1 + rhs_term2)

def check_constraint_6(bank_y, remote_processors_node_i_j, bank_set_B, inter_bank_promoted_k_y_map, intra_bank_promoted_k_u_map):
    lhs = 0.0
    for processor_k in remote_processors_node_i_j:
        lhs += inter_bank_promoted_k_y_map[processor_k][bank_y]

    rhs = 0.0
    for bank_u in bank_set_B:
        if bank_u != bank_y:
            for processor_k in remote_processors_node_i_j:
                rhs += intra_bank_promoted_k_u_map[processor_k][bank_u]

    return lhs <= rhs

def check_constraint_7(bank_y, processor_k, remote_processors_node_i_j, bank_set_B, inter_bank_promoted_k_y, intra_bank_promoted_l_u_map):
    lhs = inter_bank_promoted_k_y

    rhs = 0.0
    for bank_u in bank_set_B:
        if bank_u != bank_y:
            for processor_l in remote_processors_node_i_j:
                if processor_l != processor_k:
                    rhs += intra_bank_promoted_l_u_map[processor_l][bank_u]

    return lhs <= rhs
